const biologyReviewByTopic = new Map(biologyReviewModules.map(module=>[module.key,module]));
const biologySubject = subjects.find(subject=>subject.id==='biology');
for (const module of biologyReviewModules) {
  biologySubject.topics.push({
    key:module.key,
    title:module.title,
    term:'上',
    description:module.description,
    questions:module.questions.map(question=>({...question, subject:biologySubject.id, topic:module.key}))
  });
}
